205	function syncAboutContactHead(progress: number): void {
206	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
207	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
208	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
209	  if (!section || !head || !actions) return;
210	
211	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
212	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
213	
214	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
215	  aboutSceneDomState.isContactHeadVisible = shouldShow;
216	  aboutSceneDomState.contactHeadTimers = clearTimers(
217	    aboutSceneDomState.contactHeadTimers,
218	  );
219	
220	  if (shouldShow) {
221	    section.dataset.active = "true";
222	    head.dataset.active = "true";
223	    actions.dataset.active = "true";
224	    TextReveal.setVisibleOff(textItems);
225	    textItems.forEach((item, index) => {
226	      const timerId = window.setTimeout(() => {
227	        TextReveal.setVisibleOn(item);
228	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
229	      aboutSceneDomState.contactHeadTimers.push(timerId);
230	    });
231	    return;
232	  }
233	
234	  textItems.forEach((item) => {
235	    TextReveal.setVisibleOff(item);
236	  });
237	  section.dataset.active = "false";
238	  head.dataset.active = "false";
239	  actions.dataset.active = "false";
240	}
