29	const GALLERY_ENABLE_THRESHOLD = 0.18;
30	const MAX_GALLERY_IMAGES = 24;
31	
32	// ─── GLSL shaders (exact copy from source component) ───────────────────────
33	
34	const VERTEX_SHADER = /* glsl */ `
35	  uniform float scrollForce;
36	  uniform float time;
37	  uniform float isHovered;
38	  varying vec2 vUv;
39	  varying vec3 vNormal;
40	
41	  void main() {
42	    vUv = uv;
43	    vNormal = normal;
44	
45	    vec3 pos = position;
46	
47	    float curveIntensity = scrollForce * 0.3;
48	    float distanceFromCenter = length(pos.xy);
49	    float curve = distanceFromCenter * distanceFromCenter * curveIntensity;
50	
51	    float ripple1 = sin(pos.x * 2.0 + scrollForce * 3.0) * 0.02;
52	    float ripple2 = sin(pos.y * 2.5 + scrollForce * 2.0) * 0.015;
53	    float clothEffect = (ripple1 + ripple2) * abs(curveIntensity) * 2.0;
54	
55	    float flagWave = 0.0;
56	    if (isHovered > 0.5) {
57	      float wavePhase = pos.x * 3.0 + time * 8.0;
58	      float waveAmplitude = sin(wavePhase) * 0.1;
59	      float dampening = smoothstep(-0.5, 0.5, pos.x);
60	      flagWave = waveAmplitude * dampening;
61	      float secondaryWave = sin(pos.x * 5.0 + time * 12.0) * 0.03 * dampening;
62	      flagWave += secondaryWave;
63	    }
64	
65	    pos.z -= (curve + clothEffect + flagWave);
66	
67	    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
68	  }
69	`;
70	
71	const FRAGMENT_SHADER = /* glsl */ `
72	  uniform sampler2D map;
73	  uniform float opacity;
74	  uniform float blurAmount;
75	  uniform float scrollForce;
76	  varying vec2 vUv;
77	  varying vec3 vNormal;
78	
79	  void main() {
80	    vec4 color = texture2D(map, vUv);
81	
82	    if (blurAmount > 0.0) {
83	      vec2 texelSize = 1.0 / vec2(textureSize(map, 0));
84	      vec4 blurred = vec4(0.0);
85	      float total = 0.0;
86	
87	      for (float x = -2.0; x <= 2.0; x += 1.0) {
88	        for (float y = -2.0; y <= 2.0; y += 1.0) {
89	          vec2 offset = vec2(x, y) * texelSize * blurAmount;
90	          float weight = 1.0 / (1.0 + length(vec2(x, y)));
91	          blurred += texture2D(map, vUv + offset) * weight;
92	          total += weight;
93	        }
94	      }
95	      color = blurred / total;
96	    }
97	
98	    float curveHighlight = abs(scrollForce) * 0.05;
99	    color.rgb += vec3(curveHighlight * 0.1);
100	
101	    gl_FragColor = vec4(color.rgb, color.a * opacity);
102	  }
103	`;
104	
105	// ─── Helpers ────────────────────────────────────────────────────────────────
106	
107	function loadTexture(
108	  loader: THREE.TextureLoader,
109	  url: string,
110	  renderer: THREE.WebGLRenderer,
111	): Promise<THREE.Texture | null> {
112	  return new Promise((resolve) => {
113	    loader.load(
114	      url,
115	      (texture) => {
116	        texture.minFilter = THREE.LinearMipmapLinearFilter;
117	        texture.magFilter = THREE.LinearFilter;
118	        texture.generateMipmaps = true;
119	        texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
120	        resolve(texture);
121	      },
122	      undefined,
123	      () => resolve(null),
124	    );
125	  });
126	}
127	
128	function computeOpacity(n: number): number {
129	  if (n < FADE_IN_START) return 0;
130	  if (n < FADE_IN_END) return (n - FADE_IN_START) / (FADE_IN_END - FADE_IN_START);
131	  if (n < FADE_OUT_START) return 1;
132	  if (n < FADE_OUT_END) return 1 - (n - FADE_OUT_START) / (FADE_OUT_END - FADE_OUT_START);
133	  return 0;
134	}
135	
136	function computeBlur(n: number): number {
137	  if (n < BLUR_IN_START) return MAX_BLUR;
138	  if (n < BLUR_IN_END) return MAX_BLUR * (1 - (n - BLUR_IN_START) / (BLUR_IN_END - BLUR_IN_START));
139	  if (n < BLUR_OUT_START) return 0;
140	  if (n < BLUR_OUT_END) return MAX_BLUR * ((n - BLUR_OUT_START) / (BLUR_OUT_END - BLUR_OUT_START));
141	  return MAX_BLUR;
142	}
