161	export class InfiniteGalleryRenderer {
162	  private _renderer: THREE.WebGLRenderer | null = null;
163	  private _scene: THREE.Scene | null = null;
164	  private _camera: THREE.PerspectiveCamera | null = null;
165	  private _clock: THREE.Clock | null = null;
166	  private _raycaster: THREE.Raycaster | null = null;
167	  private _canvas: HTMLCanvasElement | null = null;
168	
169	  private _planes: PlaneRecord[] = [];
170	  private _meshList: THREE.Object3D[] = [];
171	  private _textures: (THREE.Texture | null)[] = [];
172	  private _geometries: THREE.BufferGeometry[] = [];
173	  private _materials: THREE.ShaderMaterial[] = [];
174	
175	  private _rafId: number | null = null;
176	  private _rendering = false;
177	  private _disposed = false;
178	
179	  private _resizeObserver: ResizeObserver | null = null;
180	  private _intersectionObserver: IntersectionObserver | null = null;
181	
182	  private _scrollVelocity = 0;
183	  private _lastInteractionMs = 0;
184	  private _isAutoPlaying = false;
185	  private _galleryEnabled = false;
186	  private _imageCount = 0;
187	  private _autoPlayIntervalId: ReturnType<typeof setInterval> | null = null;
188	  private _hoveredIndex = -1;
189	  private _touchLastY = 0;
190	
191	  private readonly _pointerNDC = new THREE.Vector2();
192	
193	  private readonly _onWheel: (e: WheelEvent) => void;
194	  private readonly _onKeyDown: (e: KeyboardEvent) => void;
195	  private readonly _onTouchStart: (e: TouchEvent) => void;
196	  private readonly _onTouchMove: (e: TouchEvent) => void;
197	  private readonly _onPointerMove: (e: PointerEvent) => void;
198	  private readonly _onPointerLeave: (e: PointerEvent) => void;
199	
200	  constructor() {
201	    this._onWheel = (e) => {
202	      e.preventDefault();
203	      this._recordInteraction();
204	      this._scrollVelocity += e.deltaY * 0.01 * SCROLL_SPEED;
205	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
206	    };
207	    this._onKeyDown = (e) => {
208	      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
209	        this._recordInteraction();
210	        this._scrollVelocity += 2 * SCROLL_SPEED;
211	      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
212	        this._recordInteraction();
213	        this._scrollVelocity -= 2 * SCROLL_SPEED;
214	      }
215	    };
216	    this._onTouchStart = (e) => {
217	      if (e.touches[0]) this._touchLastY = e.touches[0].clientY;
218	      this._recordInteraction();
219	    };
220	    this._onTouchMove = (e) => {
221	      e.preventDefault();
222	      if (!e.touches[0]) return;
223	      const y = e.touches[0].clientY;
224	      const delta = this._touchLastY - y;
225	      this._touchLastY = y;
226	      this._recordInteraction();
227	      this._scrollVelocity += delta * 0.03 * SCROLL_SPEED;
228	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
229	    };
230	    this._onPointerMove = (e) => {
231	      const canvas = this._canvas;
232	      const camera = this._camera;
233	      const raycaster = this._raycaster;
234	      if (!canvas || !camera || !raycaster) return;
235	      const rect = canvas.getBoundingClientRect();
236	      this._pointerNDC.set(
237	        ((e.clientX - rect.left) / rect.width) * 2 - 1,
238	        -((e.clientY - rect.top) / rect.height) * 2 + 1,
239	      );
240	      raycaster.setFromCamera(this._pointerNDC, camera);
241	      const intersects = raycaster.intersectObjects(this._meshList, false);
242	      if (intersects.length > 0) {
243	        const hit = intersects[0]?.object;
244	        this._hoveredIndex = this._planes.findIndex((r) => r.mesh === hit);
245	      } else {
246	        this._hoveredIndex = -1;
247	      }
248	    };
249	    this._onPointerLeave = (_e) => {
250	      this._hoveredIndex = -1;
251	    };
252	  }
253	
254	  async init(canvas: HTMLCanvasElement): Promise<void> {
255	    this._canvas = canvas;
256	
257	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
258	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
259	    renderer.setClearAlpha(0);
260	    this._renderer = renderer;
261	
262	    const scene = new THREE.Scene();
263	    this._scene = scene;
264	
265	    const w = Math.max(canvas.clientWidth, 1);
266	    const h = Math.max(canvas.clientHeight, 1);
267	    const camera = new THREE.PerspectiveCamera(55, w / h, 0.1, 200);
268	    camera.position.set(0, 0, 0);
269	    this._camera = camera;
270	
271	    this._clock = new THREE.Clock();
272	    this._raycaster = new THREE.Raycaster();
273	
274	    let imageUrls: string[] = [];
275	    try {
276	      const response = await fetchWorksList(0, MAX_GALLERY_IMAGES, null);
277	      imageUrls = response.items
278	        .map((item: WorkApiItem) => item.fileAttach1 || item.thumbnailImage)
279	        .filter((url) => url.length > 0)
280	        .slice(0, MAX_GALLERY_IMAGES);
281	    } catch {
282	      // fallback: no images → _buildPlanes handles empty array
283	    }
284	    if (this._disposed) return;
285	
286	    const loader = new THREE.TextureLoader();
287	    const textures = await Promise.all(imageUrls.map((url) => loadTexture(loader, url, renderer)));
288	    if (this._disposed) return;
289	
290	    this._imageCount = textures.length;
291	    this._textures = textures;
292	    this._buildPlanes(textures);
293	    this._syncSize();
294	    this._observeResize();
295	    this._observeVisibility();
296	    this._attachInputListeners();
297	
298	    this._autoPlayIntervalId = setInterval(() => this._tickAutoPlay(), 100);
299	  }
300	
301	  setScrollProgress(p: number): void {
302	    const shouldEnable = p >= GALLERY_ENABLE_THRESHOLD;
303	    if (this._galleryEnabled === shouldEnable) return;
304	    this._galleryEnabled = shouldEnable;
305	    if (!shouldEnable) {
306	      this._isAutoPlaying = false;
307	      this._scrollVelocity = 0;
308	    } else {
309	      this._lastInteractionMs = 0;
310	    }
311	  }
312	
313	  dispose(): void {
314	    this._disposed = true;
315	    this._stopRaf();
316	
317	    if (this._autoPlayIntervalId !== null) {
318	      clearInterval(this._autoPlayIntervalId);
319	      this._autoPlayIntervalId = null;
320	    }
321	
322	    if (this._canvas) this._detachInputListeners();
323	
324	    this._resizeObserver?.disconnect();
325	    this._resizeObserver = null;
326	    this._intersectionObserver?.disconnect();
327	    this._intersectionObserver = null;
328	
329	    this._geometries.forEach((g) => g.dispose());
330	    this._geometries = [];
331	    this._materials.forEach((m) => m.dispose());
332	    this._materials = [];
333	    this._textures.forEach((t) => t?.dispose());
334	    this._textures = [];
335	
336	    this._renderer?.dispose();
337	    this._renderer?.forceContextLoss();
338	    this._renderer = null;
339	    this._scene = null;
340	    this._camera = null;
341	    this._clock = null;
342	    this._raycaster = null;
343	    this._canvas = null;
344	    this._planes = [];
345	    this._meshList = [];
346	  }
347	
348	  private _buildPlanes(textures: (THREE.Texture | null)[]): void {
349	    const count = textures.length;
350	    if (count === 0) return;
351	    const scene = this._scene!;
352	
353	    for (let i = 0; i < VISIBLE_COUNT; i++) {
354	      // Spatial spread matching the original golden-angle distribution
355	      const hAngle = (i * 2.618) % (Math.PI * 2);
356	      const vAngle = (i * 1.618 + Math.PI / 3) % (Math.PI * 2);
357	      const hRadius = (i % 3) * 1.2;
358	      const vRadius = ((i + 1) % 4) * 0.8;
359	      const x = (Math.sin(hAngle) * hRadius * MAX_HORIZONTAL_OFFSET) / 3;
360	      const y = (Math.cos(vAngle) * vRadius * MAX_VERTICAL_OFFSET) / 4;
361	      const z = (DEPTH_RANGE / VISIBLE_COUNT) * i;
362	      const imageIndex = i % count;
363	
364	      const geo = new THREE.PlaneGeometry(1, 1, 32, 32);
365	      this._geometries.push(geo);
366	
367	      const mat = new THREE.ShaderMaterial({
368	        transparent: true,
369	        uniforms: {
370	          map: { value: textures[imageIndex] ?? null },
371	          opacity: { value: 0.0 },
372	          blurAmount: { value: 0.0 },
373	          scrollForce: { value: 0.0 },
374	          time: { value: 0.0 },
375	          isHovered: { value: 0.0 },
376	        },
377	        vertexShader: VERTEX_SHADER,
378	        fragmentShader: FRAGMENT_SHADER,
379	      });
380	      this._materials.push(mat);
381	
382	      const mesh = new THREE.Mesh(geo, mat);
383	      mesh.position.set(x, y, z - HALF_RANGE);
384	      this._applyTextureScale(mesh, textures[imageIndex] ?? null);
385	
386	      scene.add(mesh);
387	      this._planes.push({ mesh, data: { index: i, z, imageIndex, x, y } });
388	      this._meshList.push(mesh);
389	    }
390	  }
391	
392	  private _applyTextureScale(
393	    mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>,
394	    tex: THREE.Texture | null,
395	  ): void {
396	    const img = tex?.image as { width?: number; height?: number } | undefined;
397	    if (img?.width && img.height) {
398	      const aspect: number = img.width / img.height;
399	      mesh.scale.set(aspect > 1 ? 4 * aspect : 4, aspect > 1 ? 4 : 4 / aspect, 1);
400	    } else {
401	      mesh.scale.set(4, 4, 1);
402	    }
403	  }
404	
405	  private readonly _tick = (): void => {
406	    if (this._disposed || !this._rendering) return;
407	    this._rafId = requestAnimationFrame(this._tick);
408	
409	    const clock = this._clock!;
410	    const renderer = this._renderer!;
411	    const scene = this._scene!;
412	    const camera = this._camera!;
413	    const count = this._imageCount;
414	    if (count === 0) {
415	      renderer.render(scene, camera);
416	      this._rafId = requestAnimationFrame(this._tick);
417	      return;
418	    }
419	
420	    const delta = Math.min(clock.getDelta(), MAX_DELTA);
421	    const elapsedTime = clock.elapsedTime;
422	
423	    // Frame-rate-independent exponential damping
424	    this._scrollVelocity *= Math.pow(SCROLL_DAMPING, delta * 60);
425	    if (Math.abs(this._scrollVelocity) < 0.0001) this._scrollVelocity = 0;
426	
427	    if (this._isAutoPlaying) {
428	      this._scrollVelocity += AUTO_PLAY_ACCEL * delta;
429	      if (this._scrollVelocity > MAX_SCROLL_VEL) this._scrollVelocity = MAX_SCROLL_VEL;
430	    }
431	
432	    const scrollForceUniform = Math.min(Math.abs(this._scrollVelocity) * 0.1, 1);
433	
434	    for (const record of this._planes) {
435	      const { mesh, data } = record;
436	      const mat = mesh.material;
437	
438	      data.z += this._scrollVelocity * delta * 10;
439	
440	      if (data.z >= DEPTH_RANGE) {
441	        data.z -= DEPTH_RANGE;
442	        data.imageIndex = (data.imageIndex + 1) % count;
443	        mat.uniforms["map"].value = this._textures[data.imageIndex] ?? null;
444	        this._applyTextureScale(mesh, this._textures[data.imageIndex] ?? null);
445	      } else if (data.z < 0) {
446	        data.z += DEPTH_RANGE;
447	        data.imageIndex = ((data.imageIndex - 1) % count + count) % count;
448	        mat.uniforms["map"].value = this._textures[data.imageIndex] ?? null;
449	        this._applyTextureScale(mesh, this._textures[data.imageIndex] ?? null);
450	      }
451	
452	      mesh.position.z = data.z - HALF_RANGE;
453	
454	      const n = data.z / DEPTH_RANGE;
455	      mat.uniforms["opacity"].value = computeOpacity(n);
456	      mat.uniforms["blurAmount"].value = computeBlur(n);
457	      mat.uniforms["scrollForce"].value = scrollForceUniform;
458	      mat.uniforms["time"].value = elapsedTime;
459	      mat.uniforms["isHovered"].value = data.index === this._hoveredIndex ? 1.0 : 0.0;
460	    }
461	
462	    renderer.render(scene, camera);
463	  };
464	
465	  private _startRaf(): void {
466	    if (this._rafId !== null || this._disposed) return;
467	    this._rendering = true;
468	    this._rafId = requestAnimationFrame(this._tick);
469	  }
470	
471	  private _stopRaf(): void {
472	    this._rendering = false;
473	    if (this._rafId !== null) {
474	      cancelAnimationFrame(this._rafId);
475	      this._rafId = null;
476	    }
477	  }
478	
479	  private _recordInteraction(): void {
480	    this._lastInteractionMs = performance.now();
481	    this._isAutoPlaying = false;
482	  }
483	
484	  private _tickAutoPlay(): void {
485	    if (this._disposed) {
486	      if (this._autoPlayIntervalId !== null) {
487	        clearInterval(this._autoPlayIntervalId);
488	        this._autoPlayIntervalId = null;
489	      }
490	      return;
491	    }
492	    if (!this._galleryEnabled) {
493	      this._isAutoPlaying = false;
494	      return;
495	    }
496	    this._isAutoPlaying = performance.now() - this._lastInteractionMs > IDLE_THRESHOLD_MS;
497	  }
498	
499	  private _syncSize(): void {
500	    const canvas = this._canvas;
501	    const renderer = this._renderer;
502	    const camera = this._camera;
503	    if (!canvas || !renderer || !camera) return;
504	    const w = canvas.clientWidth;
505	    const h = canvas.clientHeight;
506	    if (w <= 0 || h <= 0) return;
507	    renderer.setSize(w, h, false);
508	    camera.aspect = w / h;
509	    camera.updateProjectionMatrix();
510	  }
511	
512	  private _observeResize(): void {
513	    if (!this._canvas) return;
514	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
515	    this._resizeObserver.observe(this._canvas);
516	  }
517	
518	  private _observeVisibility(): void {
519	    if (!this._canvas) return;
520	    this._intersectionObserver = new IntersectionObserver(
521	      (entries) => {
522	        if (entries[0]?.isIntersecting) {
523	          this._startRaf();
524	        } else {
525	          this._stopRaf();
526	        }
527	      },
528	      { threshold: 0 },
529	    );
530	    this._intersectionObserver.observe(this._canvas);
531	  }
532	
533	  private _attachInputListeners(): void {
534	    const canvas = this._canvas!;
535	    canvas.addEventListener("wheel", this._onWheel, { passive: false });
536	    canvas.addEventListener("touchstart", this._onTouchStart, { passive: true });
537	    canvas.addEventListener("touchmove", this._onTouchMove, { passive: false });
538	    canvas.addEventListener("pointermove", this._onPointerMove);
539	    canvas.addEventListener("pointerleave", this._onPointerLeave);
540	    window.addEventListener("keydown", this._onKeyDown);
541	  }
542	
543	  private _detachInputListeners(): void {
544	    const canvas = this._canvas!;
545	    canvas.removeEventListener("wheel", this._onWheel);
546	    canvas.removeEventListener("touchstart", this._onTouchStart);
547	    canvas.removeEventListener("touchmove", this._onTouchMove);
548	    canvas.removeEventListener("pointermove", this._onPointerMove);
549	    canvas.removeEventListener("pointerleave", this._onPointerLeave);
550	    window.removeEventListener("keydown", this._onKeyDown);
551	  }
